domain":"NONNEGATIVE_REAL","index_set":["零配件编号"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-DI","scope_ref":"P1","token":"dᵢ","meaning":"零配件i的检测成本","unit":"元/件","role":"VARIABLE","shape":"INDEXED","domain":"NONNEGATIVE_REAL","index_set":["零配件编号"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PF","scope_ref":"P1","token":"p_f","meaning":"成品的次品率（题目直接给出）","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-A","scope_ref":"P1","token":"a","meaning":"成品装配成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-DF","scope_ref":"P1","token":"d_f","meaning":"成品检测成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-S","scope_ref":"P1","token":"s","meaning":"市场售价","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-L","scope_ref":"P1","token":"l","meaning":"调换损失","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-R","scope_ref":"P1","token":"r","meaning":"不合格成品的拆解费用","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-X1","scope_ref":"P1","token":"x₁","meaning":"是否检测零配件1的决策变量","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-X2","scope_ref":"P1","token":"x₂","meaning":"是否检测零配件2的决策变量","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-X3","scope_ref":"P1","token":"x₃","meaning":"是否检测成品的决策变量","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-X4","scope_ref":"P1","token":"x₄","meaning":"是否拆解不合格成品的决策变量","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"BOOLEAN","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-EC","scope_ref":"P1","token":"EC","meaning":"单位产品的期望总成本","unit":"元/件","role":"VARIABLE","shape":"SCALAR","domain":"NONNEGATIVE_REAL","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PJ","scope_ref":"P1","token":"p_j","meaning":"第j道工序输出的次品率（题目直接给出）","unit":"无量纲","role":"VARIABLE","shape":"INDEXED","domain":"PROBABILITY","index_set":["工序编号"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-AJ","scope_ref":"P1","token":"a_j","meaning":"第j道工序的装配成本","unit":"元/件","role":"VARIABLE","shape":"INDEXED","domain":"NONNEGATIVE_REAL","index_set":["工序编号"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-DJ","scope_ref":"P1","token":"d_j","meaning":"第j道工序输出的检测成本","unit":"元/件","role":"VARIABLE","shape":"INDEXED","domain":"NONNEGATIVE_REAL","index_set":["工序编号"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-RJ","scope_ref":"P1","token":"r_j","meaning":"对第j道工序不合格输出的拆解费用","unit":"元/件","role":"VARIABLE","shape":"INDEXED","domain":"NONNEGATIVE_REAL","index_set":["工序编号"]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PHAT","scope_ref":"P1","token":"p̂","meaning":"由问题1抽样得到的次品率点估计","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PL","scope_ref":"P1","token":"p_L","meaning":"次品率置信区间下界","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"SymbolSpec","value":{"symbol_id":"S-PU","scope_ref":"P1","token":"p_U","meaning":"次品率置信区间上界（保守决策输入）","unit":"无量纲","role":"VARIABLE","shape":"SCALAR","domain":"PROBABILITY","index_set":[]}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-WORST-CASE-P1","scope_ref":"P1","statement":"情形(2)中，由于备择假设p>p₀未给出具体值，我假设企业关注的最差情况为p₁=20%（即标称值的2倍），在此假设下控制第二类错误。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":["S-P1","S-N"],"status":"ACTIVE","e1_span":"情形(2)中，由于备择假设p>p₀未给出具体值，我假设企业关注的最差情况为p₁=20%（即标称值的2倍），在此假设下控制第二类错误。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-CONSERVATIVE-DECISION","scope_ref":"P1","statement":"问题4中，我采用保守决策原则：用次品率的置信区间上界（如95%置信上限）作为决策输入，因为企业通常风险厌恶，宁可高估次品率也不愿低估导致调换损失。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":["S-PU","S-PHAT"],"status":"ACTIVE","e1_span":"问题4中，我采用保守决策原则：用次品率的置信区间上界（如95%置信上限）作为决策输入，因为企业通常风险厌恶，宁可高估次品率也不愿低估导致调换损失。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-INDEPENDENT-DEFECTS","scope_ref":"P1","statement":"各零配件次品率相互独立，成品次品率由零配件次品率按题目给定方式决定（题目直接给出成品次品率，故不涉及此假设，但拆解后零配件质量独立于装配过程）。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":["S-PI","S-PF"],"status":"ACTIVE","e1_span":"各零配件次品率相互独立，成品次品率由零配件次品率按题目给定方式决定（题目直接给出成品次品率，故不涉及此假设，但拆解后零配件质量独立于装配过程）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-LINEAR-COST","scope_ref":"P1","statement":"所有成本（检测、装配、拆解、调换）与数量线性相关，无规模效应；单位产品决策可独立进行。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":["S-DI","S-A","S-R","S-L"],"status":"ACTIVE","e1_span":"所有成本（检测、装配、拆解、调换）与数量线性相关，无规模效应；单位产品决策可独立进行。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NO-SALVAGE","scope_ref":"P1","statement":"报废的不合格零配件/成品无残值，丢弃成本为0（除已支付的购买/装配成本外）。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":["S-CI","S-A"],"status":"ACTIVE","e1_span":"报废的不合格零配件/成品无残值，丢弃成本为0（除已支付的购买/装配成本外）。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SINGLE-PERIOD","scope_ref":"P1","statement":"决策为单周期静态决策，不考虑库存、批量、时间因素；市场售价固定，不考虑供需变化。","source_type":"MODELING_CHOICE","justification_refs":["R-OUT"],"risk_level":"LOW","testable":true,"sensitivity_refs":["S-S"],"status":"ACTIVE","e1_span":"决策为单周期静态决策，不考虑库存、批量、时间因素；市场售价固定，不考虑供需变化。"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-BINOMIAL-X","scope_ref":"P1","expression":"X ~ Binomial(n, p)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-X"],"rhs_symbols":["S-N"],"equation_type":"DEFINITION","unit":"件","depends_on":[],"source":"问题1模型建立","e1_span":"设抽样n件，检出次品数X~Binomial(n,p)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-H0","scope_ref":"P1","expression":"H₀: p ≤ p₀ = 0.10","representation":"LATEX_PRESENTATION","lhs_symbols":["S-P0"],"rhs_symbols":[],"equation_type":"CONSTRAINT","unit":"无量纲","depends_on":[],"source":"问题1模型建立","e1_span":"原假设H₀: p≤p₀=0.10，备择假设H₁: p>p₀"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-REJECT-RULE","scope_ref":"P1","expression":"c = min{k : P(X ≥ k | p = p₀) ≤ 0.05}","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C-REJECT"],"rhs_symbols":["S-X","S-P0","S-ALPHA"],"equation_type":"DEFINITION","unit":"件","depends_on":["EQ-BINOMIAL-X","EQ-H0"],"source":"问题1情形(1)判定规则","e1_span":"判定规则：X≥c则拒收，其中c=min{k: P(X≥k|p=p₀)≤0.05}"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-ACCEPT-RULE","scope_ref":"P1","expression":"c' = max{k : P(X ≤ k | p = p₁) ≤ 0.10}","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C-ACCEPT"],"rhs_symbols":["S-X","S-P1","S-BETA"],"equation_type":"DEFINITION","unit":"件","depends_on":["EQ-BINOMIAL-X"],"source":"问题1情形(2)判定规则","e1_span":"则判定规则：X≤c'则接收，其中c'=max{k: P(X≤k|p=p₁)≤0.10}"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-MIN-N","scope_ref":"P1","expression":"min n s.t. ∃ c : P(X ≥ c | p₀) ≤ 0.05 ∧ P(X < c | p₁) ≤ 0.10","representation":"LATEX_PRESENTATION","lhs_symbols":["S-N"],"rhs_symbols":["S-C-REJECT","S-P0","S-P1","S-ALPHA","S-BETA"],"equation_type":"OBJECTIVE","unit":"件","depends_on":["EQ-REJECT-RULE","EQ-ACCEPT-RULE"],"source":"问题1最小样本量确定","e1_span":"找最小n使得存在判定阈值c满足P(X≥c|p₀)≤0.05且P(X<c|p₁)≤0.10。"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-COMPONENT-COST","scope_ref":"P1","expression":"cost_i = dᵢ + pᵢ·cᵢ (if inspect) ; cᵢ (if not inspect)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-DI","S-PI","S-CI"],"rhs_symbols":[],"equation_type":"DEFINITION","unit":"元/件","depends_on":[],"source":"问题2期望成本计算(1)","e1_span":"零配件阶段：若检测，成本=dᵢ+pᵢ×cᵢ（丢弃不合格件，需重新购买）；若不检测，成本=cᵢ"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-EXPECTED-COST","scope_ref":"P1","expression":"EC = Σ_k P(k) · cost(k)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-EC"],"rhs_symbols":[],"equation_type":"OBJECTIVE","unit":"元/件","depends_on":["EQ-COMPONENT-COST"],"source":"问题2方法选择：加权和法","e1_span":"F4中的加权和法（期望成本=各情形成本×概率之和）"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-DECISION-FLIP","scope_ref":"P1","expression":"inspect iff E[loss without inspection] − E[loss with inspection] > dᵢ","representation":"LATEX_PRESENTATION","lhs_symbols":["S-DI"],"rhs_symbols":[],"equation_type":"DERIVED","unit":"元/件","depends_on":["EQ-EXPECTED-COST"],"source":"问题2决策依据","e1_span":"若检测成本低于期望损失，则检测。"}},{"kind":"ModelSpec","value":{"model_id":"M-MAIN","problem_refs":["P1"],"assumption_refs":["A-WORST-CASE-P1","A-CONSERVATIVE-DECISION","A-INDEPENDENT-DEFECTS","A-LINEAR-COST","A-NO-SALVAGE","A-SINGLE-PERIOD"],"variable_refs":["S-N","S-X","S-P0","S-P1","S-ALPHA","S-BETA","S-C-REJECT","S-C-ACCEPT","S-PI","S-CI","S-DI","S-PF","S-A","S-DF","S-S","S-L","S-R","S-X1","S-X2","S-X3","S-X4","S-EC","S-PJ","S-AJ","S-DJ","S-RJ","S-PHAT","S-PL","S-PU"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1},{"symbol_ref":"S-P1","value":0.2},{"symbol_ref":"S-ALPHA","value":0.05},{"symbol_ref":"S-BETA","value":0.1}],"equation_refs":["EQ-BINOMIAL-X","EQ-H0","EQ-REJECT-RULE","EQ-ACCEPT-RULE","EQ-MIN-N","EQ-COMPONENT-COST","EQ-EXPECTED-COST","EQ-DECISION-FLIP"],"constraints":["P(拒收|p≤p₀) ≤ 0.05","P(接收|p>p₁) ≤ 0.10","x₁,x₂,x₃,x₄ ∈ {0,1}"],"objective":"在信息不完全（次品率未知或不确定）的情况下，通过抽样检测和阶段决策使企业期望成本最小化","dependencies":[]}},{"kind":"DataArtifact","value":{"data_id":"DA-OUT-Q1","locator":"out_q1.json"}},{"kind":"DataArtifact","value":{"data_id":"DA-OUT-Q23","locator":"out_q23.json"}},{"kind":"DataArtifact","value":{"data_id":"DA-OUT-Q4","locator":"out_q4.json"}}],"code":"const fs=require('fs');function logC(n,k){if(k<0||k>n)return 0;let r=1;for(let i=0;i<k;i++)r=r*(n-i)/(i+1);return r;}function binomCdf(k,n,p){let s=0;for(let i=0;i<=k;i++)s+=logC(n,i)*Math.pow(p,i)*Math.pow(1-p,n-i);return s;}function binomSf(k,n,p){return 1-binomCdf(k-1,n,p);}
const out={};
const p0=0.10,p1=0.20,alpha=0.05,beta=0.10;
let n1=1,c1=0;while(true){let found=false;for(let c=0;c<=n1;c++){if(binomSf(c,n1,p0)<=alpha){c1=c;found=true;break;}}if(found)break;n1++;}
out.case1={n:n1,c:c1,alpha_actual:binomSf(c1,n1,p0)};
let n2=1,cp=0;while(true){let found=false;for(let c=n2;c>=0;c--){if(binomCdf(c,n2,p1)<=beta){cp=c;found=true;break;}}if(found)break;n2++;}
out.case2={n:n2,c_prime:cp,beta_actual:binomCdf(cp,n2,p1)};
let nu=1,cu=0;while(true){let ok=false;for(let c=0;c<=nu;c++){if(binomSf(c,nu,p0)<=alpha&&binomCdf(c-1,nu,p1)<=beta){cu=c;ok=true;break;}}if(ok)break;nu++;}
out.unified={n:nu,c:cu,alpha_actual:binomSf(cu,nu,p0),beta_actual:binomCdf(cu-1,nu,p1)};
out.normal_approx={n_case1:Math.ceil((1.6449*Math.sqrt(p0*(1-p0))+1.2816*Math.sqrt(p1*(1-p1)))/(p1-p0))*(p1-p0)/(p1-p0)};
fs.writeFileSync('out_q1.json',JSON.stringify(out,null,2));
const cases=[{p1:0.1,p2:0.1,pf:0.1,c1:4,c2:18,d1:2,d2:3,a:6,df:3,s:56,l:6,r:5},{p1:0.2,p2:0.2,pf:0.2,c1:4,c2:18,d1:2,d2:3,a:6,df:3,s:56,l:6,r:5},{p1:0.1,p2:0.1,pf:0.1,c1:4,c2:18,d1:2,d2:3,a:6,df:3,s:56,l:30,r:5},{p1:0.2,p2:0.2,pf:0.2,c1:4,c2:18,d1:1,d2:1,a:6,df:2,s:56,l:30,r:5},{p1:0.1,p2:0.2,pf:0.1,c1:4,c2:18,d1:2,d2:3,a:6,df:3,s:56,l:10,r:5},{p1:0.2,p2:0.1,pf:0.2,c1:4,c2:18,d1:1,d2:2,a:6,df:3,s:56,l:10,r:5}];
function ec(p1,p2,pf,c1,c2,d1,d2,a,df,s,l,r,x){const ins1=x[0],ins2=x[1],insf=x[2],tear=x[3];let cost=0;const q1=ins1?p1:0,q2=ins2?p2:0;cost+=c1+d1*ins1+(ins1?p1*c1:0);cost+=c2+d2*ins2+(ins2?p2*c2:0);cost+=a;cost+=df*insf;const eff=(1-q1)*(1-q2);let outDef=1-eff;if(!insf){cost+=pf*(l+s);}else{cost+=pf*(r+(tear?(d1+d2+c1+c2):0));}return cost;}
const res=[];for(const cs of cases){let best=null;for(let m=0;m<16;m++){const x=[(m>>0)&1,(m>>1)&1,(m>>2)&1,(m>>3)&1];const v=ec(cs.p1,cs.p2,cs.pf,cs.c1,cs.c2,cs.d1,cs.d2,cs.a,cs.df,cs.s,cs.l,cs.r,x);if(best===null||v<best.v)best={v,x};}res.push({case:cases.indexOf(cs)+1,best_cost:best.v,decisions:{x1:best.x[0],x2:best.x[1],x3:best.x[2],x4:best.x[3]}});}
